import csv
import io


def column_means(csv_text: str) -> dict[str, float]:
    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)
    if not rows:
        return {}
    header = rows[0]
    data = rows[1:]
    result = {}
    for i, col_name in enumerate(header):
        values = []
        all_numeric = True
        for row in data:
            if i >= len(row):
                continue
            cell = row[i]
            if cell == '':
                continue
            try:
                values.append(float(cell))
            except ValueError:
                all_numeric = False
                break
        if all_numeric and values:
            result[col_name] = sum(values) / len(values)
    return result
